import { composeMiddleware, toRequest } from "h3";
import { HookableCore } from "hookable";
import { createMatcherFromFind, memoizeRouteRulesMatcher } from "h3/rules";

import { findRouteRules } from "#nitro/virtual/routing";
import { createNitroApp, initNitroPlugins } from "#nitro/virtual/app";
const APP_ID = import.meta.prerender ? "prerender" : "default";
export function useNitroApp() {
	let instance = useNitroApp._instance;
	if (instance) {
		return instance;
	}
	instance = useNitroApp._instance = createNitroApp();
	globalThis.__nitro__ = globalThis.__nitro__ || {};
	globalThis.__nitro__[APP_ID] = instance;
	initNitroPlugins(instance);
	return instance;
}
export function useNitroHooks() {
	const nitroApp = useNitroApp();
	const hooks = nitroApp.hooks;
	if (hooks) {
		return hooks;
	}
	return nitroApp.hooks = new HookableCore();
}
export function serverFetch(resource, init, context) {
	const req = toRequest(resource, init);
	req.context = {
		...req.context,
		...context
	};
	const appHandler = useNitroApp().fetch;
	try {
		return Promise.resolve(appHandler(req));
	} catch (error) {
		return Promise.reject(error);
	}
}



const kWebSocketHooks = /* @__PURE__ */ Symbol.for("crossws.hooks");
export async function resolveWebsocketHooks(req) {
	
	
	
	const res = await serverFetch(req);
	const carrier = req;
	return res.crossws ?? carrier[kWebSocketHooks] ?? carrier.context?.[kWebSocketHooks] ?? {};
}
export function fetch(resource, init, context) {
	if (typeof resource === "string" && resource.charCodeAt(0) === 47) {
		return serverFetch(resource, init, context);
	}
	resource = resource._request || resource;
	return globalThis.fetch(resource, init);
}
let _matchRouteRules;
export function getRouteRules(method, pathname) {
	return (_matchRouteRules ??= memoizeRouteRulesMatcher(createMatcherFromFind(findRouteRules)))(method, pathname);
}

export function createRouteRulesMiddleware() {
	const composed = new WeakMap();
	const middleware = (event, next) => {
		const ruleMiddleware = getRouteRules(event.req.method, event.url.pathname).routeRuleMiddleware;
		if (ruleMiddleware.length === 0) {
			return next();
		}
		let chain = composed.get(ruleMiddleware);
		if (!chain) {
			chain = composeMiddleware(ruleMiddleware);
			composed.set(ruleMiddleware, chain);
		}
		return chain(event, next);
	};
	return markUntraced(middleware);
}

export function createRoutedMiddleware(findRoutedMiddleware) {
	const root = { children: new Map() };
	const middleware = (event, next) => {
		const matched = findRoutedMiddleware(event.req.method, event.url.pathname);
		if (matched.length === 0) {
			return next();
		}
		let node = root;
		for (const entry of matched) {
			let child = node.children.get(entry);
			if (!child) {
				child = { children: new Map() };
				node.children.set(entry, child);
			}
			node = child;
		}
		return (node.chain ??= composeMiddleware(matched.map((r) => r.data)))(event, next);
	};
	return markUntraced(middleware);
}


function markUntraced(middleware) {
	middleware.__traced__ = true;
	return middleware;
}
